export const getCourseContent = (courseId: string, moduleIndex: number, phaseIndex: number) => {
  const course = WERSEE_COURSES.find(c => c.id === courseId);
  if (!course) return null;

  const module = course.content[moduleIndex];
  if (module && module.phases[phaseIndex]) {
    return module.phases[phaseIndex];
  }

  return null;
};
